"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/shared/lib/cn"

const brandIconVariants = cva("inline-block shrink-0", {
  variants: {
    size: {
      xs: "size-3.5",
      sm: "size-4",
      md: "size-5",
      lg: "size-6",
      xl: "size-8",
    },
  },
  defaultVariants: {
    size: "md",
  },
})

type BrandIconProps = Omit<React.SVGProps<SVGSVGElement>, "children"> &
  VariantProps<typeof brandIconVariants>

type BrandIconRenderer = React.ReactNode | ((uid: string) => React.ReactNode)

function createBrandIcon(render: BrandIconRenderer, displayName: string) {
  const BrandIcon = React.forwardRef<SVGSVGElement, BrandIconProps>(function BrandIcon(
    { className, size, ...props },
    ref,
  ) {
    const reactId = React.useId().replace(/:/g, "")
    const glyph = typeof render === "function" ? render(reactId) : render

    return (
      <svg
        ref={ref}
        viewBox="0 0 24 24"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        aria-hidden="true"
        className={cn(brandIconVariants({ size }), className)}
        {...props}
      >
        {glyph}
      </svg>
    )
  })
  BrandIcon.displayName = displayName
  return BrandIcon
}

